import AppKit

struct PositionAutomation:Codable,Equatable {
    var mode=0,shape=0,speed=0,freeRate=25,depth=100;var scanMode:Int?;var anchors:[Int]?
    static let scans=["Full region","Anchors / Step","Anchors / Morph"]
    var markerValues:[Int]{anchors?.count==5 ? anchors!:[0,250,500,750,1000]}
    var scan:Int{scanMode ?? 0}
    static let modes=["Off","LFO / Tempo sync","LFO / Free Hz"]
    static let shapes=["Triangle","Sine","Saw","Reverse Saw","Square","Random S&H"]
    static let rates:[(String,Int)]=[("128",24576),("96",18432),("64",12288),("48",9216),("32",6144),("24",4608),("16",3072),("12",2304),("8",1536),("6",1152),("4",768),("3",576),("2",384),("3/2",288),("1",192),("3/4",144),("1/2",96),("3/8",72),("1/3",64),("1/4",48),("3/16",36),("1/6",32),("1/8",24),("1/12",16),("1/16",12),("1/24",8),("1/32",6),("1/48",4),("1/64",3)]
    var normalized:PositionAutomation{var p=self;p.mode=max(0,min(2,mode));p.shape=max(0,min(5,shape));p.speed=max(0,min(Self.rates.count-1,speed));p.freeRate=max(5,min(2000,freeRate));p.depth=max(0,min(100,depth));if let scan=p.scanMode{p.scanMode=max(0,min(2,scan))};if p.anchors != nil{p.anchors=p.markerValues.map{max(0,min(1000,$0))}};return p}
    var engineRate:Int{mode==2 ? freeRate:Self.rates[speed].1}
    var speedLabel:String{mode==2 ? String(format:"%.2f Hz",Double(freeRate)/100):Self.rates[speed].0+" step"}
    func shapeValue(_ phase:Double)->Double{switch shape{case 0:return 1-abs(2*phase-1);case 1:return 0.5-0.5*cos(2*Double.pi*phase);case 2:return phase;case 3:return 1-phase;case 4:return phase<0.5 ? 0:1;default:return phase<0.5 ? 0.18:0.78}}
}

extension Tracker {
    var positionAutomation:PositionAutomation{(sampleSettings.positionAutomation ?? PositionAutomation()).normalized}
    func openPositionAutomation(){guard samplerFrames>0,sampleSettings.mode==5 else{message="Choose a sample in Granular mode first (9)";return};automationFocus=0;modal=7;needsDisplay=true}
    func adjustPositionAutomation(_ d:Int){var a=positionAutomation;let sign=d>0 ? 1:-1;switch automationFocus{case 0:a.mode=(a.mode+sign+3)%3;case 1:a.shape=(a.shape+sign+PositionAutomation.shapes.count)%PositionAutomation.shapes.count;case 2:if a.mode==2{a.freeRate=max(5,min(2000,a.freeRate+d*5))}else{a.speed=max(0,min(PositionAutomation.rates.count-1,a.speed+sign))};case 3:a.depth=max(0,min(100,a.depth+d*5));case 4:a.scanMode=(a.scan+sign+3)%3;case 5...9:var markers=a.markerValues;markers[automationFocus-5]=max(0,min(1000,markers[automationFocus-5]+d*5));a.anchors=markers;if a.scan==0{a.scanMode=1};default:break};var p=sampleSettings;p.positionAutomation=a.normalized;setSampleSettings(p)}
    func automationKey(_ e:NSEvent){let code=e.keyCode,ch=e.charactersIgnoringModifiers?.lowercased() ?? "";if e.modifierFlags.contains(.option),let i=padCodes.firstIndex(of:code){pad(i);return};if e.modifierFlags.contains(.command)&&code==18{samplePreview();return};if let n=Int(ch),(0...4).contains(n){automationFocus=5+n;needsDisplay=true;return};switch code{case 53,36,76:modal=0;case 125:automationFocus=min(9,automationFocus+1);case 126:automationFocus=max(0,automationFocus-1);case 49,122:samplePreview();case 123:adjustPositionAutomation(-1);case 124:adjustPositionAutomation(1);default:if ch=="q"||ch=="e"{adjustPositionAutomation((ch=="e" ? 1:-1)*(e.modifierFlags.contains(.shift) ? 10:1))}};needsDisplay=true}
    func automationBox()->NSRect{let w=min(860,bounds.width-40),h=min(540,bounds.height-50);return NSRect(x:(bounds.width-w)/2,y:(bounds.height-h)/2,width:w,height:h)}
    func drawPositionAutomation(){let b=automationBox(),a=positionAutomation,p=sampleSettings;rect(0,0,bounds.width,bounds.height,.black.withAlphaComponent(0.60));rect(b.minX,b.minY,b.width,b.height,trackerBackground);border(b.minX,b.minY,b.width,b.height,gray(0.65));rect(b.minX,b.minY,b.width,38,gray(0.26));txt("INSTRUMENT AUTOMATION / GRANULAR POSITION",b.minX+15,b.minY+12,12,teal,true);let values=[PositionAutomation.modes[a.mode],PositionAutomation.shapes[a.shape],a.speedLabel,"\(a.depth)%",PositionAutomation.scans[a.scan]],labels=["Type","Shape","Speed","Depth","Scan"];for i in 0..<5{let y=b.minY+48+CGFloat(i)*32;if i==automationFocus{rect(b.minX+12,y,b.width-24,29,gray(0.31));border(b.minX+12,y,b.width-24,29,teal)};txt(labels[i],b.minX+25,y+7,12,gray(0.85));txt(values[i],b.minX+b.width*0.40,y+7,12,i==automationFocus ? teal:yellow,true)};let gx=b.minX+25,gy=b.minY+222,gw=b.width-50,gh=max(40,b.height-340);rect(gx,gy,gw,gh,gray(0.09));let cols=max(1,min(800,Int(gw))),peaks=wavePeaksForRange(p.start,p.end,cols),mid=gy+gh/2,path=NSBezierPath();for i in 0..<cols{let x=gx+CGFloat(i)*gw/CGFloat(cols);path.move(to:NSPoint(x:x,y:mid-CGFloat(peaks[i].1)*gh*0.42));path.line(to:NSPoint(x:x,y:mid-CGFloat(peaks[i].0)*gh*0.42))};gray(0.70).setStroke();path.lineWidth=1;path.stroke();let effective=a.mode==0 ? p.position:Int(tm_sample_position(Int32(instrumentRow)));rect(gx+gw*CGFloat(effective)/1000,gy,2,gh,teal);for i in 0..<5{let x=gx+gw*CGFloat(a.markerValues[i])/1000;let color=automationFocus==i+5 ? recColor:yellow;rect(x,gy+16,2,gh-16,color);txt("\(i)",min(x+3,gx+gw-13),gy+4,10,color,true);let bx=gx+CGFloat(i)*gw/5,by=gy+gh+12;if automationFocus==i+5{rect(bx,by,gw/5-4,30,gray(0.32))};centered(String(format:"%d: %.1f%%",i,Double(a.markerValues[i])/10),bx,by+7,gw/5-4,11,color,true)};txt("0–4 select anchor • click waveform / Q/E set position • Step jumps, Morph interpolates",gx,gy+gh+51,11,gray(0.8));centered("↑ ↓ Select    Q/E Change    F1 Preview    Enter / Esc Close",b.minX,b.maxY-24,b.width,11,gray(0.75))}
    func automationMouse(_ p:NSPoint){let b=automationBox(),gx=b.minX+25,gy=b.minY+222,gw=b.width-50,gh=max(40,b.height-340);if p.y>=b.minY+48&&p.y<b.minY+208&&b.contains(p){automationFocus=Int((p.y-b.minY-48)/32)}else if p.x>=gx&&p.x<=gx+gw&&p.y>=gy+gh+12&&p.y<gy+gh+42{automationFocus=5+min(4,Int((p.x-gx)/(gw/5)))}else if p.x>=gx&&p.x<=gx+gw&&p.y>=gy&&p.y<=gy+gh{if automationFocus<5{automationFocus=5};var a=positionAutomation,marks=a.markerValues;marks[automationFocus-5]=max(0,min(1000,Int((p.x-gx)/gw*1000)));a.anchors=marks;if a.scan==0{a.scanMode=1};var s=sampleSettings;s.positionAutomation=a;setSampleSettings(s)};needsDisplay=true}
}
